import {createComplexRowSlabs} from './complex-plane-row-slabs.js';
import {createSegmentedBytes} from './segmented-bytes.js';
import {EngineError,requireValue,controlCheckpoint,checkAbort} from './errors.js';
// Interleaved binary32/binary64 real/imaginary pairs, always in global row-major order.
export async function createComplexPlane(width,height,{ArrayType=Float32Array,rowSlabBytes=0,...options}){
 requireValue(Number.isSafeInteger(width)&&Number.isSafeInteger(height)&&width>0&&height>0,'Invalid complex plane dimensions.');requireValue(ArrayType===Float32Array||ArrayType===Float64Array,'Invalid complex plane precision.');requireValue(Number.isSafeInteger(rowSlabBytes)&&rowSlabBytes>=0,'Invalid complex row staging limit.');const stride=2*ArrayType.BYTES_PER_ELEMENT,store=await createSegmentedBytes(width*height*stride,options);
 const slabs=rowSlabBytes?createComplexRowSlabs({store,width,stride,budget:options.budget,maximumBytes:rowSlabBytes}):null;let writes=Promise.resolve(),closing=false,closeFlight;const active=new Set();const track=task=>{active.add(task);task.then(()=>active.delete(task),()=>active.delete(task));return task;};
 const enqueueWrite=work=>{const task=writes.then(work);writes=task.catch(()=>{});return task;};
 const range=(x,y,w,h)=>requireValue([x,y,w,h].every(Number.isSafeInteger)&&x>=0&&y>=0&&w>0&&h>0&&x+w<=width&&y+h<=height,'Complex region outside plane.');
 const plane={width,height,store,ArrayType,
  async read(x,y,w,h,{signal,cooperate}={}){range(x,y,w,h);requireValue(cooperate===undefined||typeof cooperate==='function','Invalid complex transfer cooperator.');if(cooperate)checkAbort(signal);if(slabs){await writes;checkAbort(signal);}const out=new ArrayType(w*h*2),bytes=new Uint8Array(out.buffer);if(slabs&&await slabs.read(bytes,x,y,w,h,{signal,cooperate}))return out;if(x===0&&w===width){await store.readInto(bytes,y*width*stride);if(cooperate)checkAbort(signal);return out;}for(let row=0;row<h;row++){if(row%128===0){if(cooperate)checkAbort(signal);await (cooperate??controlCheckpoint)(signal);if(cooperate)checkAbort(signal);}await store.readInto(bytes.subarray(row*w*stride,(row+1)*w*stride),((y+row)*width+x)*stride);}if(cooperate)checkAbort(signal);return out;},
  async write(values,x,y,w,h,{signal,cooperate}={}){range(x,y,w,h);requireValue(cooperate===undefined||typeof cooperate==='function','Invalid complex transfer cooperator.');if(cooperate)checkAbort(signal);requireValue(values instanceof ArrayType&&values.length===w*h*2,'Complex region size mismatch.');const bytes=new Uint8Array(values.buffer,values.byteOffset,values.byteLength);const execute=async()=>{if(slabs)checkAbort(signal);if(slabs&&await slabs.write(bytes,x,y,w,h,{signal,cooperate}))return;if(x===0&&w===width){await store.write(bytes,y*width*stride);if(cooperate)checkAbort(signal);return;}for(let row=0;row<h;row++){if(row%128===0){if(cooperate)checkAbort(signal);await (cooperate??controlCheckpoint)(signal);if(cooperate)checkAbort(signal);}await store.write(bytes.subarray(row*w*stride,(row+1)*w*stride),((y+row)*width+x)*stride);}if(cooperate)checkAbort(signal);};return slabs?enqueueWrite(execute):execute();},
  dispose:()=>store.dispose()
 };
 if(slabs){const read=plane.read.bind(plane),write=plane.write.bind(plane);for(const [name,fn]of [['read',read],['write',write]])plane[name]=(...args)=>{if(closing)return Promise.reject(new EngineError('DISPOSED','Complex plane is closing.'));return track(fn(...args));};plane.dispose=()=>{if(closeFlight)return closeFlight;closing=true;const task=(async()=>{while(active.size)await Promise.allSettled([...active]);await store.dispose();})();closeFlight=task;void task.catch(()=>{if(closeFlight===task)closeFlight=null;});return task;};}
 return plane;
}
